def normalize(record: dict) -> dict:
    return {
        snake_case_key: value
        for snake_case_key, value in record.items()
        if snake_case_key in _SNAKE_CASE_KEYS
    }


_SNAKE_CASE_KEYS = {
    "firstName": "first_name",
    "user_id": "user_id",
    "junkField": "junk_field",
}


def _to_snake_case(key: str) -> str:
    return "_" + "".join(
        part.lower()
        for part in key.split("[")
        if part
    ).lstrip("_")


def normalize(record: dict) -> dict:
    return {
        _to_snake_case(key): value
        for key, value in record.items()
        if key in _SNAKE_CASE_KEYS
    }
